{
  "items": [
    {
      "name": "MvPolynomial.optionEquivLeft_coeff_coeff",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ (R : Type u) {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial (Option σ) R) (m : ℕ) (d : σ →₀ ℕ),\n  MvPolynomial.coeff d (((MvPolynomial.optionEquivLeft R σ) p).coeff m) = MvPolynomial.coeff (Finsupp.optionElim m d) p"
    },
    {
      "name": "MvPolynomial.optionEquivLeft",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "definition",
      "type": "(R : Type u) → (S₁ : Type v) → [inst : CommSemiring R] → MvPolynomial (Option S₁) R ≃ₐ[R] Polynomial (MvPolynomial S₁ R)"
    },
    {
      "name": "MvPolynomial.finSuccEquiv",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "definition",
      "type": "(R : Type u) →\n  [inst : CommSemiring R] → (n : ℕ) → MvPolynomial (Fin (n + 1)) R ≃ₐ[R] Polynomial (MvPolynomial (Fin n) R)"
    },
    {
      "name": "MvPolynomial.optionEquivLeft_coeff_some_coeff_none",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ (R : Type u) (S₁ : Type v) [inst : CommSemiring R] (n : Option S₁ →₀ ℕ) (f : MvPolynomial (Option S₁) R),\n  MvPolynomial.coeff n.some (((MvPolynomial.optionEquivLeft R S₁) f).coeff (n none)) = MvPolynomial.coeff n f"
    },
    {
      "name": "AlgebraicIndependent.mvPolynomialOptionEquivPolynomialAdjoin",
      "module_name": "Mathlib.RingTheory.AlgebraicIndependent.Basic",
      "kind": "definition",
      "type": "{ι : Type u} →\n  {R : Type u_2} →\n    {A : Type v} →\n      {x : ι → A} →\n        [inst : CommRing R] →\n          [inst_1 : CommRing A] →\n            [inst_2 : Algebra R A] →\n              AlgebraicIndependent R x → MvPolynomial (Option ι) R ≃+* Polynomial ↥(Algebra.adjoin R (Set.range x))"
    },
    {
      "name": "MvPolynomial.optionEquivLeft_apply",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ (R : Type u) (S₁ : Type v) [inst : CommSemiring R] (a : MvPolynomial (Option S₁) R),\n  (MvPolynomial.optionEquivLeft R S₁) a =\n    (MvPolynomial.aeval fun o => o.elim Polynomial.X fun s => Polynomial.C (MvPolynomial.X s)) a"
    },
    {
      "name": "MvPolynomial.optionEquivLeft_X_some",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ (R : Type u) (S₁ : Type v) [inst : CommSemiring R] (x : S₁),\n  (MvPolynomial.optionEquivLeft R S₁) (MvPolynomial.X (some x)) = Polynomial.C (MvPolynomial.X x)"
    },
    {
      "name": "MvPolynomial.image_support_finSuccEquiv",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommSemiring R] {n : ℕ} {f : MvPolynomial (Fin (n + 1)) R} {i : ℕ},\n  Finset.image (Finsupp.cons i) (((MvPolynomial.finSuccEquiv R n) f).coeff i).support = {m ∈ f.support | m 0 = i}"
    }
  ]
}
